var uniformArray = function(nums1) {
    function canMakeAll(targetParity) {
        const globalMin = [Infinity, Infinity];
        for (const x of nums1) {
            globalMin[x % 2] = Math.min(globalMin[x % 2], x);
        }

        for (const x of nums1) {
            const curParity = x % 2;
            if (curParity === targetParity) {
